 const items = this.getItems();\n    const index = items.indexOf(current);\n    const prev = index > 0 ? index - 1 : items.length - 1;\n    items[prev]?.focus();\n  }\n}\n","<div class=\"card h-100 border shadow-sm solicitud-card\">\n  <div class=\"card-header bg-transparent d-flex justify-content-between align-items-center px-3 py-2\">\n    <span class=\"fw-semibold text-body-secondary small\">{{ solicitud().folio }}</span>\n    <div class=\"d-flex gap-1\">\n      @if (solicitud().semaforo; as s) {\n        <span class=\"badge rounded-pill\" [class]=\"semaforoBadgeClass(s.color)\">\n          {{ s.diasRestantes > 0 ? s.diasRestantes + ' d' : 'Vencida' }}\n        </span>\n      }\n      <span class=\"badge rounded-pill\" [class]=\"solicitud().statusClass\">{{ solicitud().status }}</span>\n    </div>\n  </div>\n\n  <div class=\"card-body d-flex flex-column gap-2 px-3 py-2\">\n    <h6 class=\"card-title mb-0\">{{ solicitud().proyecto }}</h6>\n    <p class=\"text-secondary small mb-0\">{{ solicitud().solicitante }}</p>\n\n    <hr class=\"my-1\" />\n\n    <div class=\"d-flex flex-column gap-1\">\n      <div class=\"d-flex align-items-center gap-2 text-secondary small\">\n        <i class=\"bi bi-calendar-event\"></i>\n        <span class=\"fw-medium\">Recepción:</span>\n        <span>{{ solicitud().fechaRecepcion }}</span>\n      </div>\n      <div class=\"d-flex align-items-center gap-2 text-secondary small\">\n        <i class=\"bi bi-calendar-check\"></i>\n        <span class=\"fw-medium\">Sesión:</span>\n        <span>{{ solicitud().fechaSesion }}</span>\n      </div>\n      <div class=\"d-flex align-items-center gap-2 text-secondary small\">\n        <i class=\"bi bi-flag\"></i>\n        <span class=\"fw-medium\">Resolución:</span>\n        <span>{{ solicitud().fechaResolucion }}</span>\n      </div>\n      @if (solicitud().metricas) {\n        <div class=\"d-flex align-items-center gap-2 text-secondary small\">\n          <i class=\"bi bi-hourglass-split\"></i>\n          <span class=\"fw-medium\">Tiempo:</span>\n          <span>{{ solicitud().metricas!.diasTranscurridos }} / {{ solicitud().metricas!.diasLimite }} días</span>\n          @if (solicitud().metricas!.fueraDeLimite) {\n            <span class=\"badge bg-danger\">Fuera de límite</span>\n          } @else {\n            <span class=\"badge bg-success\">En tiempo</span>\n          }\n        </div>\n      }\n    </div>\n  </div>\n\n  <div class=\"card-footer bg-transparent d-flex justify-content-between align-items-center px-3 py-2 border-top\">\n    @if (accionPrincipal(); as accion) {\n      <button\n        type=\"button\"\n        class=\"btn btn-sm btn-primary me-2\"\n        [attr.aria-label]=\"accion.label + ' ' + solicitud().folio\"\n        (click)=\"onAccionPrincipal()\"\n      >\n        <i class=\"bi bi-plus-circle me-1\"></i>{{ accion.label }}\n      </button>\n    } @else {\n      <button\n        type=\"button\"\n        class=\"btn btn-sm btn-outline-primary me-2 fw-semibold\"\n        [attr.aria-label]=\"'Ver solicitud ' + solicitud().folio\"\n        (click)=\"onVer()\"\n      >\n        <i class=\"bi bi-eye me-1\"></i>Ver solicitud\n      </button>\n    }\n\n    <div class=\"dropdown\">\n      <button appDropdown #trigger=\"appDropdown\" [dropdownMenu]=\"menu\" aria-haspopup=\"menu\"\n        [attr.aria-label]=\"'Acciones para ' + solicitud().folio\"\n        class=\"btn btn-sm btn-outline-secondary dropdown-toggle dropdown-toggle-split\">\n        <span class=\"visually-hidden\">Acciones</span>\n      </button>\n      <div #menu role=\"menu\" tabindex=\"-1\" class=\"dropdown-menu dropdown-menu-end\" [class.show]=\"trigger.open()\"\n        (keydown)=\"trigger.onMenuKeydown($event)\" (click)=\"trigger.onMenuClick($event)\">\n        <button role=\"menuitem\" class=\"dropdown-item\" (click)=\"onVer()\">\n          <i class=\"bi bi-eye me-2\"></i>Ver solicitud\n        </button>\n        <button role=\"menuitem\" class=\"dropdown-item\" (click)=\"onDescargar()\">\n          <i class=\"bi bi-download me-2\"></i>Descargar documentos\n        </button>\n      </div>\n    </div>\n  </div>\n</div>","import { Component, output, input } from '@angular/core';\nimport { Solicitud } from '../../models/solicitud.model';\nimport { DropdownDirective } from '../../directives/dropdown.directive';\nimport { semaforoBadgeClass } from '../../models/solicitud-status.util';\n\n@Component({\n  selector: 'app-solicitud-card',\n  imports: [DropdownDirective],\n  templateUrl: './solicitud-card.component.html',\n  styleUrl: './solicitud-card.component.scss',\n  host: { class: 'col' },\n})\nexport class SolicitudCardComponent {\n  solicitud = input.required<Solicitud>();\n  accionPrincipal = input<{ label: string; route: string } | undefined>(undefined);\n\n  verSolicitud = output<string>();\n  descargar = output<string>();\n  accionPrincipalClick = output<string>();\n\n  onVer(): void {\n    this.verSolicitud.emit(this.solicitud().folio);\n  }\n\n  onDescargar(): void {\n    this.descargar.emit(this.solicitud().folio);\n  }\n\n  onAccionPrincipal(): void {\n    this.accionPrincipalClick.emit(this.solicitud().folio);\n  }\n\n  protected readonly semaforoBadgeClass = semaforoBadgeClass;\n}\n","<td class=\"fw-semibold\">{{ solicitud().folio }}</td>\n<td>{{ solicitud().solicitante }}</td>\n<td>{{ solicitud().proyecto }}</td>\n<td>{{ solicitud().fechaRecepcion }}</td>\n<td>{{ solicitud().fechaSesion }}</td>\n<td>{{ solicitud().fechaResolucion }}</td>\n<td>\n  <span class=\"badge rounded-pill\" [class]=\"solicitud().statusClass\">\n    {{ solicitud().status }}\n  </span>\n</td>\n<td>\n  @if (solicitud().semaforo; as s) {\n    <span class=\"badge rounded-pill\" [class]=\"semaforoBadgeClass(s.color)\">\n      {{ s.diasRestantes > 0 ? s.diasRestantes + ' d' : 'Vencida' }}\n    </span>\n  } @else {\n    <span class=\"text-muted\">&mdash;</span>\n  }\n</td>\n@if (mostrarMetricas()) {\n  <td>\n    @if (solicitud().metricas; as m) {\n      <div class=\"small\">\n        <span class=\"fw-bold\">{{ m.diasTranscurridos }}</span> / {{ m.diasLimite }} días\n        @if (m.fueraDeLimite) {\n          <span class=\"badge bg-danger ms-1\">Fuera de límite</span>\n        } @else {\n          <span class=\"badge bg-success ms-1\">En tiempo</span>\n        }\n        <div class=\"text-muted\">{{ m.porcentajeCompletado }}% completado</div>\n      </div>\n    } @else {\n      <span class=\"text-muted\">—</span>\n    }\n  </td>\n}\n<td class=\"position-relative\">\n  @if (accionPrincipal(); as accion) {\n    <button\n      type=\"button\"\n      class=\"btn btn-sm btn-primary me-2\"\n      [attr.aria-label]=\"accion.label + ' ' + solicitud().folio\"\n      (click)=\"onAccionPrincipal()\"\n    >\n      <i class=\"bi bi-plus-circle me-1\"></i>{{ accion.label }}\n    </button>\n  } @else {\n    <button\n      type=\"button\"\n      class=\"btn btn-sm btn-outline-primary me-2 fw-semibold\"\n      [attr.aria-label]=\"'Ver solicitud ' + solicitud().folio\"\n      (click)=\"onVer()\"\n    >\n      <i class=\"bi bi-eye me-1\"></i>Ver solicitud\n    </button>\n  }\n  <button\n    #trigger=\"appDropdown\"\n    appDropdown\n    [dropdownMenu]=\"menu\"\n    class=\"btn btn-sm btn-outline-secondary border-0\"\n    [attr.aria-label]=\"'Acciones para ' + solicitud().folio\"\n  >\n    <i class=\"bi bi-three-dots-vertical\"></i>\n  </button>\n  <div\n    #menu\n    role=\"menu\"\n    tabindex=\"-1\"\n    class=\"dropdown-menu\"\n    [class.show]=\"trigger.open()\"\n    (keydown)=\"trigger.onMenuKeydown($event)\"\n    (click)=\"trigger.onMenuClick($event)\"\n  >\n    <button role=\"menuitem\" class=\"dropdown-item d-flex align-items-center gap-2 px-3 py-2 fw-semibold\" (click)=\"onVer()\">\n      <i class=\"bi bi-eye\"></i> Ver solicitud\n    </button>\n    <button role=\"menuitem\" class=\"dropdown-item d-flex align-items-center gap-2 px-3 py-2\" (click)=\"onDescargar()\">\n      <i class=\"bi bi-download\"></i> Descargar documentos\n    </button>\n  </div>\n</td>\n","import { Component, output, input } from '@angular/core';\nimport { Solicitud } from '../../models/solicitud.model';\nimport { DropdownDirective } from '../../directives/dropdown.directive';\nimport { semaforoBadgeClass } from '../../models/solicitud-status.util';\n\n@Component({\n  // Selector de atributo requerido: este componente se renderiza como <tr appSolicitudRow>\n  // dentro de una tabla, no puede usar un selector de elemento estándar.\n  // eslint-disable-next-line @angular-eslint/component-selector\n  selector: 'tr[appSolicitudRow]',\n  imports: [DropdownDirective],\n  templateUrl: './solicitud-row.component.html',\n  styleUrl: './solicitud-row.component.scss',\n})\nexport class SolicitudRowComponent {\n  solicitud = input.required<Solicitud>();\n  mostrarMetricas = input(false);\n  accionPrincipal = input<{ label: string; route: string } | undefined>(undefined);\n\n  verSolicitud = output<string>();\n  descargar = output<string>();\n  accionPrincipalClick = output<string>();\n\n  onVer(): void {\n    this.verSolicitud.emit(this.solicitud().folio);\n  }\n\n  onDescargar(): void {\n    this.descargar.emit(this.solicitud().folio);\n  }\n\n  onAccionPrincipal(): void {\n    this.accionPrincipalClick.emit(this.solicitud().folio);\n  }\n\n  protected readonly semaforoBadgeClass = semaforoBadgeClass;\n}\n","<div class=\"d-flex justify-content-end mb-3\">\n  <div role=\"group\" aria-label=\"Vista de autorizaciones\" class=\"btn-group\">\n    <button\n      type=\"button\"\n      class=\"btn\"\n      [class]=\"viewMode() === 'cards' ? 'btn-primary' : 'btn-outline-secondary'\"\n      [attr.aria-pressed]=\"viewMode() === 'cards'\"\n      aria-label=\"Vista tarjetas\"\n      (click)=\"setViewMode('cards')\">\n      <i class=\"bi bi-grid-3x3-gap\"></i>\n    </button>\n    <button\n      type=\"button\"\n      class=\"btn\"\n      [class]=\"viewMode() === 'table' ? 'btn-primary' : 'btn-outline-secondary'\"\n      [attr.aria-pressed]=\"viewMode() === 'table'\"\n      aria-label=\"Vista tabla\"\n      (click)=\"setViewMode('table')\">\n      <i class=\"bi bi-table\"></i>\n    </button>\n  </div>\n</div>\n\n@if (solicitudes().length === 0) {\n  <div class=\"text-center py-5\">\n    <i class=\"bi bi-inbox display-1 text-secondary d-block mb-3\"></i>\n    <p class=\"fs-5 text-secondary mb-0\">No hay autorizaciones para mostrar</p>\n  </div>\n} @else if (viewMode() === 'cards') {\n  <div class=\"row row-cols-1 row-cols-md-2 row-cols-xl-3 g-3\">\n    @for (s of solicitudes(); track s.folio) {\n      <app-solicitud-card\n        [solicitud]=\"s\"\n        [accionPrincipal]=\"accionPrincipal()\"\n        (verSolicitud)=\"verSolicitud.emit($event)\"\n        (descargar)=\"descargar.emit($event)\"\n        (accionPrincipalClick)=\"accionPrincipalClick.emit($event)\" />\n    }\n  </div>\n} @else {\n  <div class=\"table-responsive rounded shadow overflow-hidden border\">\n    <table class=\"table table-hover align-middle mb-0\">\n      <thead class=\"bg-primary text-white\">\n        <tr>\n          <th scope=\"col\">Folio</th>\n          <th scope=\"col\">Solicitante</th>\n          <th scope=\"col\">Proyecto</th>\n          <th scope=\"col\">Recepci&oacute;n</th>\n          <th scope=\"col\">Sesi&oacute;n</th>\n          <th scope=\"col\">Resoluci&oacute;n</th>\n          <th scope=\"col\">Estatus</th>\n          @if (mostrarMetricas()) {\n            <th scope=\"col\">Tiempo de seguimiento</th>\n          }\n          <th scope=\"col\">Sem&aacute;foro</th>\n          <th scope=\"col\">Acciones</th>\n        </tr>\n      </thead>\n      <tbody>\n        @for (s of solicitudes(); track s.folio) {\n          <tr\n            appSolicitudRow\n            [solicitud]=\"s\"\n            [mostrarMetricas]=\"mostrarMetricas()\"\n            [accionPrincipal]=\"accionPrincipal()\"\n            (verSolicitud)=\"verSolicitud.emit($event)\"\n            (descargar)=\"descargar.emit($event)\"\n            (accionPrincipalClick)=\"accionPrincipalClick.emit($event)\"></tr>\n        }\n      </tbody>\n    </table>\n  </div>\n}\n","import { Component, input, output } from '@angular/core';\nimport { Solicitud } from '../../models/solicitud.model';\nimport { SolicitudCardComponent } from './solicitud-card.component';\nimport { SolicitudRowComponent } from './solicitud-row.component';\n\n@Component({\n  selector: 'app-solicitud-list',\n  imports: [SolicitudCardComponent, SolicitudRowComponent],\n  templateUrl: './solicitud-list.component.html',\n  styleUrl: './solicitud-list.component.scss',\n})\nexport class SolicitudListComponent {\n  solicitudes = input.required<Solicitud[]>();\n  viewMode = input<'cards' | 'table'>('cards');\n  mostrarMetricas = input(false);\n  accionPrincipal = input<{ label: string; route: string } | undefined>(undefined);\n\n  verSolicitud = output<string>();\n  descargar = output<string>();\n  accionPrincipalClick = output<string>();\n  viewModeChange = output<'cards' | 'table'>();\n\n  setViewMode(mode: 'cards' | 'table'): void {\n    this.viewModeChange.emit(mode);\n  }\n}\n","import { Injectable } from '@angular/core';\nimport * as XLSX from 'xlsx-js-style';\nimport type { Solicitud } from '../shared/models/solicitud.model';\n\nexport interface ExcelExportOptions {\n  fileName?: string;\n  sheetName?: string;\n}\n\n@Injectable({ providedIn: 'root' })\nexport class ExcelExportService {\n  private readonly headers = [\n    'Folio',\n    'Solicitante',\n    'Proyecto',\n    'Fecha Recepción',\n    'Fecha Sesión',\n    'Fecha Resolución',\n    'Estatus',\n  ];\n\n  private readonly headerStyle: XLSX.CellStyle = {\n    font: { bold: true, color: { rgb: 'FFFFFF' } },\n    fill: { fgColor: { rgb: '002F2A' } },\n    border: { bottom: { style: 'thin', color: { rgb: '000000' } } },\n  };\n\n  build(solicitudes: Solicitud[], options?: ExcelExportOptions): void {\n    const rows = solicitudes.map((s) => [\n      s.folio,\n      s.solicitante,\n      s.proyecto,\n      s.fechaRecepcion,\n      s.fechaSesion,\n      s.fechaResolucion,\n      s.status,\n    ]);\n\n    const aoa: unknown[][] = [this.headers, ...rows];\n    const ws = XLSX.utils.aoa_to_sheet(aoa);\n\n    this.applyHeaderStyle(ws);\n    this.autoSizeColumns(ws, aoa);\n\n    const wb = XLSX.utils.book_new();\n    const sheetName = options?.sheetName ?? 'Autorizaciones';\n    XLSX.utils.book_append_sheet(wb, ws, sheetName);\n\n    const fileName = options?.fileName ?? this.defaultFileName();\n    XLSX.writeFile(wb, fileName);\n  }\n\n  private applyHeaderStyle(ws: XLSX.WorkSheet): void {\n    this.headers.forEach((_, colIndex) => {\n      const cellRef = XLSX.utils.encode_cell({ r: 0, c: colIndex });\n      const cell = ws[cellRef];\n      if (cell) {\n        cell.s = this.headerStyle;\n      }\n    });\n  }\n\n  private autoSizeColumns(ws: XLSX.WorkSheet, aoa: unknown[][]): void {\n    const colCount = this.headers.length;\n    const widths: number[] = new Array(colCount).fill(12);\n\n    for (const row of aoa) {\n      for (let c = 0; c < colCount; c++) {\n        const val = row[c];\n        const len = val != null ? String(val).length : 0;\n        widths[c] = Math.max(widths[c], len + 2);\n      }\n    }\n\n    ws['!cols'] = widths.map((w) => ({ wch: Math.min(w, 40) }));\n  }\n\n  private defaultFileName(): string {\n    const now = new Date();\n    const yyyy = now.getFullYear();\n    const mm = String(now.getMonth() + 1).padStart(2, '0');\n    const dd = String(now.getDate()).padStart(2, '0');\n    return `autorizaciones-${yyyy}-${mm}-${dd}.xlsx`;\n  }\n}\n","<div class=\"container py-4\">\n\n  <!-- Header row: title + action buttons -->\n  <div class=\"d-flex justify-content-between align-items-center mb-4\">\n    <div>\n      <h1 class=\"mb-0\">{{ title() }}</h1>\n    </div>\n    <div class=\"d-flex align-items-center gap-2\">\n      @if (showNuevaButton()) {\n        <a class=\"btn btn-primary\" [routerLink]=\"nuevaRoute()\">\n          <i class=\"bi bi-plus-lg me-2\"></i>Nueva solicitud\n        </a>\n      }\n      <button class=\"btn btn-secondary\" (click)=\"onDescargar()\" [disabled]=\"isExporting()\">\n        <i class=\"bi bi-download me-2\"></i>Descargar informe\n      </button>\n    </div>\n  </div>\n\n  @if (!seccionTramite()) {\n  <!-- Search bar + filter toggle -->\n  <div class=\"mb-3\">\n    <div class=\"d-flex align-items-center gap-2\">\n      <div class=\"input-group\" style=\"max-width: 400px;\">\n        <span class=\"input-group-text\"><i class=\"bi bi-search\"></i></span>\n        <input\n          type=\"text\"\n          class=\"form-control\"\n          placeholder=\"Buscar por folio o solicitante...\"\n          [value]=\"searchTerm()\"\n          (input)=\"onSearchInput($event)\">\n      </div>\n      <button class=\"btn btn-outline-secondary\" (click)=\"toggleFilters()\">\n        <i [class]=\"showFilters() ? 'bi bi-funnel-fill' : 'bi bi-funnel'\"></i> Filtros\n      </button>\n    </div>\n  </div>\n\n  <!-- Filter row: status + date filters (collapsible) -->\n  @if (showFilters()) {\n  <div class=\"row g-3 mb-4\">\n    @if (!statusPreset()) {\n    <div class=\"col-md-4\">\n      <label class=\"form-label\" for=\"filtro-estatus\">Estatus</label>\n      <select\n        class=\"form-select\"\n        id=\"filtro-estatus\"\n        [value]=\"statusFilter()\"\n        (change)=\"onStatusChange($event)\">\n        @for (s of statuses; track s) {\n          <option [value]=\"s\">{{ s }}</option>\n        }\n      </select>\n    </div>\n    } @else {\n    <div class=\"col-md-4\">\n      <span class=\"form-label fw-semibold d-block\">Estatus</span>\n      <div class=\"form-control-plaintext\">{{ statusPresetLabel() }}</div>\n    </div>\n    }\n    <div class=\"col-md-4\">\n      <label class=\"form-label\" for=\"filtro-fecha-recepcion\">Fecha recepci&oacute;n</label>\n      <input\n        type=\"date\"\n        class=\"form-control\"\n        id=\"filtro-fecha-recepcion\"\n        [value]=\"fechaRecepcionFilter()\"\n        (change)=\"onFechaChange($event)\">\n    </div>\n  </div>\n  }\n  }\n\n  <!-- Loading state -->\n  @if (isLoading()) {\n  <div class=\"text-center py-5\">\n    <div class=\"spinner-border text-primary\" role=\"status\">\n      <span class=\"visually-hidden\">Cargando…</span>\n    </div>\n    <p class=\"mt-3 text-secondary\">Cargando solicitudes…</p>\n  </div>\n  }\n\n  <app-solicitud-list\n    [solicitudes]=\"allSolicitudes()\"\n    [viewMode]=\"viewMode()\"\n    [mostrarMetricas]=\"mostrarMetricas()\"\n    [accionPrincipal]=\"accionPrincipal()\"\n    (viewModeChange)=\"setViewMode($event)\"\n    (verSolicitud)=\"onVer($event)\"\n    (accionPrincipalClick)=\"onAccionPrincipal($event)\"\n  />\n\n  @if (paginationMeta().lastPage > 1) {\n  <app-paginator\n    [currentPage]=\"paginationMeta().currentPage\"\n    [lastPage]=\"paginationMeta().lastPage\"\n    [total]=\"paginationMeta().total\"\n    [perPage]=\"paginationMeta().perPage\"\n    (pageChange)=\"onPageChange($event)\"\n    (pageSizeChange)=\"onPageSizeChange($event)\"\n  />\n  }\n</div>\n","import { Component, inject, input, signal, computed, resource, effect } from '@angular/core';\nimport { Router, RouterLink, ActivatedRoute } from '@angular/router';\nimport { firstValueFrom } from 'rxjs';\nimport { SolicitudListComponent } from '../solicitud-list/solicitud-list.component';\nimport { PaginatorComponent } from '../paginator/paginator.component';\nimport { SolicitudService } from '../../services/solicitud.service';\nimport { TramiteService } from '../../services/tramite.service';\nimport { SOLICITUD_STATUSES } from '../../models/solicitud-status.util';\nimport { SeccionTramite } from '../../models/seccion-tramite.enum';\nimport { ExcelExportService } from '../../../services/excel-export.service';\n\n@Component({\n  selector: 'app-autorizaciones-list',\n  imports: [RouterLink, SolicitudListComponent, PaginatorComponent],\n  templateUrl: './autorizaciones-list.component.html',\n  styleUrl: './autorizaciones-list.component.scss',\n})\nexport class AutorizacionesListComponent {\n  private readonly router = inject(Router);\n  private readonly route = inject(ActivatedRoute);\n  private readonly solicitudService = inject(SolicitudService);\n  private readonly tramiteService = inject(TramiteService);\n  private readonly excelExportService = inject(ExcelExportService);\n\n  readonly title = input.required<string>();\n  readonly verBaseRoute = input.required<string>();\n  readonly showNuevaButton = input(false);\n  readonly nuevaRoute = input('');\n  readonly statusPreset = input<string[]>();\n  readonly mostrarMetricas = input(false);\n  readonly accionPrincipal = input<{ label: string; route: string } | undefined>(undefined);\n  readonly seccionTramite = input<SeccionTramite | undefined>(undefined);\n\n  readonly statusPresetLabel = computed(() => {\n    const preset = this.statusPreset();\n    return preset ? preset.join(', ') : '';\n  });\n\n  readonly showFilters = signal(false);\n  readonly viewMode = signal<'cards' | 'table'>('cards');\n\n  readonly searchTerm = signal('');\n  readonly statusFilter = signal('Todos');\n  readonly fechaRecepcionFilter = signal('');\n  readonly page = signal(1);\n  readonly perPage = signal(15);\n  readonly isExporting = signal(false);\n\n  readonly queryParams = computed(() => ({\n    search: this.searchTerm().trim() || undefined,\n    status: this.statusFilter() === 'Todos' ? undefined : this.statusFilter(),\n    dateFrom: this.fechaRecepcionFilter() || undefined,\n    dateTo: this.fechaRecepcionFilter() || undefined,\n    page: this.page(),\n    perPage: this.perPage(),\n    conMetricas: this.mostrarMetricas(),\n  }));\n\n  readonly solicitudesResource = resource({\n    params: () => this.queryParams(),\n    loader: async ({ params }) => {\n      const seccion = this.seccionTramite();\n      if (seccion) {\n        return firstValueFrom(\n          this.tramiteService.getSolicitudesPorTramite(seccion, params.page, params.perPage),\n        );\n      }\n      return firstValueFrom(this.solicitudService.getSolicitudes(params));\n    },\n  });\n\n  readonly allSolicitudes = computed(() =>\n    this.solicitudesResource.hasValue() ? this.solicitudesResource.value()!.data : [],\n  );\n\n  readonly paginationMeta = computed(() => {\n    const v = this.solicitudesResource.value();\n    return v\n      ? { currentPage: v.current_page, lastPage: v.last_page, total: v.total, perPage: v.per_page }\n      : { currentPage: 1, lastPage: 1, total: 0, perPage: 15 };\n  });\n\n  readonly isLoading = computed(() => this.solicitudesResource.isLoading());\n\n  readonly statuses = ['Todos', ...SOLICITUD_STATUSES];\n\n  constructor() {\n    effect(() => {\n      const preset = this.statusPreset();\n      if (preset) {\n        this.statusFilter.set(preset.join(','));\n      }\n    });\n  }\n\n  toggleFilters(): void {\n    this.showFilters.update(v => !v);\n  }\n\n  setViewMode(mode: 'cards' | 'table'): void {\n    this.viewMode.set(mode);\n  }\n\n  onSearchInput(event: Event): void {\n    this.searchTerm.set((event.target as HTMLInputElement).value);\n    this.page.set(1);\n  }\n\n  onStatusChange(event: Event): void {\n    this.statusFilter.set((event.target as HTMLSelectElement).value);\n    this.page.set(1);\n  }\n\n  onFechaChange(event: Event): void {\n    this.fechaRecepcionFilter.set((event.target as HTMLInputElement).value);\n    this.page.set(1);\n  }\n\n  onPageChange(page: number): void {\n    this.page.set(page);\n  }\n\n  onPageSizeChange(size: number): void {\n    this.perPage.set(size);\n    this.page.set(1);\n  }\n\n  onVer(folio: string): void {\n    const backPath = this.route.snapshot.data?.['backPath'];\n    if (backPath) {\n      this.router.navigate([this.verBaseRoute(), folio], { queryParams: { from: backPath } });\n    } else {\n      this.router.navigate([this.verBaseRoute(), folio]);\n    }\n  }\n\n  onAccionPrincipal(folio: string): void {\n    const accion = this.accionPrincipal();\n    if (accion) {\n      if (this.seccionTramite()) {\n        this.router.navigate([accion.route, folio, 'revision']);\n      } else {\n        this.router.navigate([accion.route, folio, 'tramites']);\n      }\n    }\n  }\n\n  async onDescargar(): Promise<void> {\n    const params = {\n      search: this.queryParams().search,\n      status: this.queryParams().status,\n      dateFrom: this.queryParams().dateFrom,\n      dateTo: this.queryParams().dateTo,\n    };\n    this.isExporting.set(true);\n    try {\n      const result = await firstValueFrom(this.solicitudService.getSolicitudesForExport(params));\n      this.excelExportService.build(result.data);\n    } finally {\n      this.isExporting.set(false);\n    }\n  }\n}\n"],"names":["require_cpexcel","__commonJSMin","exports","module","cptable","D","e","i","j","root","factory","__require","cpt","magic","sbcs_cache","dbcs_cache","magic_cache","magic_decode","magic_encode","cpdcache","cpecache","sfcc","x","cca","has_buf","Buffer_from","nbfs","buf","enc","n","mdl","mdb","make_EE","E","EE","keys","len","ee","sbcs_encode","cp","data","ofmt","out","w","sbcs_decode","DD","d","c","dbcs_encode","f","jj","k","dbcs_decode","utf8_d","ww","direct","encache","s","null_enc","cp_decache","decache","last_enc","last_cp","cache","BM","SetD","encode","C","M","isstr","tt","decode","F","dash","o64","c1","c2","c3","e1","e2","e3","e4","l","hascp","require_xlsx_min","XLSX","make_xlsx_lib","a","re","_","t","ie","h","ae","r","ne","u","oe","p","o","te","se","ce","le","fe","he","m","ue","de","pe","v","Ge","T","g","A","R","me","b","y","L","S","O","I","N","P","ve","U","B","W","H","z","V","G","X","K","Y","J","q","Z","Q","ge","be","we","Te","Ee","ke","ye","Se","_e","xe","Dr","xr","hr","ur","Lr","_r","$","Cr","Fr","Ae","Ce","Ut","Re","Oe","Ie","Ne","Fe","De","Pe","Le","Me","Ue","Be","We","He","ze","Ve","je","$e","Xe","Ye","Ke","Je","qe","Ze","Qe","et","rt","at","nt","st","it","ot","ct","lt","ft","ht","ut","dt","pt","mt","gt","bt","vt","wt","